// The video filter refused this scene's clip. Count the attempt PER SCENE
// (static data): the START IMAGE is regenerated with a steer and the SAME
// scene resubmitted in place, up to MAX_ATTEMPTS times, the second steer
// stronger than the first. Only after that does the scene get marked rejected
// and the loop move on.
//
// WHY THE STILL AND NOT THE PROMPT (2026-09-22). This ladder used to rewrite
// the MOTION prompt four times on one seed. Both refusal classes that matter
// are triggered by the picture, not the words: `PROMINENT` was proven so in
// docs/lessons-pipeline.md ("a fully generic prompt with no names still failed
// on the same image"), and `AUDIO_GENERATION_FILTERED` on 2026-09-22 — seven
// generations of one still, three of them with a blank prompt and different
// seeds, all refused; a different still of the same desk passed first time
// (db/port/audio-filter/README.md, db/port/pool-tail-and-refusals/README.md).
// So the ladder now asks for a new still through the same `scene-image-regen`
// webhook the site's Regenerate button fires, waits for it to land, and
// resubmits. The motion prompt is rewritten only when the reason names a
// PERSON, since a real name in the direction re-triggers regardless of the
// still.
const sd = $getWorkflowStaticData('global');
sd.rewrites = sd.rewrites || {};
const cur = $('Current Scene').first().json || {};
const f = cur.fields || {};
const sceneId = cur.id;
const n = (sd.rewrites[sceneId] || 0) + 1;
sd.rewrites[sceneId] = n;
const MAX_ATTEMPTS = 2;
// NOT slice(0, 2000). The marker that says WHICH filter fired sits inside
// `media[0].mediaStatus`, past a kilobyte of request echo, and on a longer
// response the old 2,000-character window cut it off — so every refusal read
// as the generic one. 2026-09-22.
const errText = JSON.stringify($json).slice(0, 20000);
const audioFiltered = errText.includes('AUDIO_GENERATION_FILTERED') || errText.includes('AUDIO_FILTERED');
const prominent = errText.includes('PROMINENT');
const minor = errText.includes('MINOR');
let reason = 'Google video content filter';
if (prominent) reason = 'the shot shows or names a recognizable real person';
else if (minor) reason = 'the shot places a child on screen';
else if (audioFiltered) reason = 'Google refused the generated AUDIO track, not the picture (AUDIO_GENERATION_FILTERED)';
const kind = prominent ? 'person' : (minor ? 'minor' : (audioFiltered ? 'audio' : 'generic'));

// The steer rides to the image model as `Observații Scenă`, which
// `IR Build Request` appends to the stored image prompt as an ADJUSTMENT
// REQUEST — the same slot the producer's own correction uses. The `AUTO-`
// prefix is what tells every other reader of that field (`VRW Build Regen`,
// `Evaluate Image Approval`, `Prep Video Regen`) it is machine text, and
// `IR Write Image` clears it when the new still lands. Phrased as what the
// frame CONTAINS, since an instruction written as an absence is the documented
// way to get the thing named.
const STEER = {
  audio: 'Keep the same moment, place and light, framed on the setting, the objects and the hands: any person is seen from behind or stands outside the frame, every mouth out of view, so the still reads as a quiet room rather than someone about to speak.',
  person: 'Keep the same moment, place and light, with every face turned away from the camera or outside the frame: people from behind, in profile at a distance, or a detail insert of hands and objects.',
  minor: 'Keep the same moment, place and light, with adults only or the empty setting, every child outside the frame.',
  generic: 'Keep the same moment, place and light, framed on the setting, the objects and the light, with any person seen from behind or outside the frame.',
};
const STRONGER = 'Keep the same place and light as a still life: the setting, the objects and the light only, every person outside the frame.';
const steer = 'AUTO-STEER: ' + (n >= 2 ? STRONGER : STEER[kind]);

// What the give-up note tells the producer to DO. `Mark Video Prompt
// Rejected` prints this verbatim after the reason.
const advice = audioFiltered
  ? 'Two new stills were tried automatically and Google still refused the soundtrack it invents for them. Write the image prompt as a moment with nobody about to speak — the room, the objects, hands — regenerate the image, approve it, then press Regenerate video.'
  : 'Two new stills were tried automatically and Google still refused. The picture is what it refuses: rewrite the image prompt so no face or real person is in frame, regenerate the image, approve it, then press Regenerate video.';

console.log('Scene ' + sceneId + ': video filter refusal (' + reason + '), attempt ' + n + '/' + MAX_ATTEMPTS + (n > MAX_ATTEMPTS ? ' — giving up' : ' — regenerating the still'));
return [{ json: {
  sceneId,
  imageId: String(f['Image Media ID'] || ''),
  prompt: String(f['Video Scenă URL'] || ''),
  note: String(f['Observații Scenă'] || ''),
  reason,
  kind,
  advice,
  steer,
  audioFiltered,
  attempt: n,
  giveUp: n > MAX_ATTEMPTS,
} }];

// Fold the result of ONE tick back into the pool, then hand control to Pool Tick.
//
// Five edges arrive here, and they mean different things. They are told apart by
// $prevNode.name rather than by sniffing the item's shape, because the shapes
// are whatever the previous node happened to return (an HTTP response, a
// Postgres result, Current Scene's object) and a shape test would silently
// mis-read the day one of them changes.
//
// With the pool OFF this node is a pass-through: Pool Tick never ran, so there
// is no state, and Pool Return? sends the item on to Loop Scenes exactly as
// before. Nothing about the serial path changes.

let pool = null;
try { pool = $('Pool Tick').first().json.pool || null; } catch (e) { pool = null; }

if (!pool) {
  // Pool is off. Pass the item through untouched.
  return $input.all();
}

let from = '';
try { from = String($prevNode.name || ''); } catch (e) { from = ''; }

let scene = null;
try { scene = $('Current Scene').first().json; } catch (e) { scene = null; }
const sceneId = String((scene && scene.id) || '');

const inflight = pool.inflight || [];
const queue = pool.queue || [];
const done = pool.done || [];

const drop = function (id) {
  pool.inflight = inflight.filter(function (j) { return j.id !== id; });
};
const unqueue = function (id) {
  pool.queue = queue.filter(function (q) { return q.id !== id; });
};

if (from === 'Pool Submitted?') {
  // A job was accepted by Flow. This covers the first submit of a scene AND a
  // motion re-roll, which resubmits from inside a POLL tick — so the entry is
  // replaced rather than added, and the poll counter starts again.
  let jobid = '';
  try { jobid = String($('Submit Video').first().json.jobid || ''); } catch (e) { jobid = '';}
  const q = queue.find(function (x) { return x.id === sceneId; });
  // A resubmit from inside a poll tick — a motion re-roll, or the refusal
  // ladder after a new still — arrives on a RELOADED scene row that carries no
  // poolAccount, and its queue entry was removed on the first submit. Before
  // 2026-09-22 that filed the new job under account '' and freed the real
  // account's slot while the job was still running, so the pool could put a
  // second job on that account. The entry being replaced knows the account.
  const prev = inflight.find(function (x) { return x.id === sceneId; });
  const account = (q && q.account) || (scene && scene.poolAccount) || (prev && prev.account) || '';
  drop(sceneId);
  unqueue(sceneId);
  if (jobid) {
    pool.inflight.push({ id: sceneId, account: account, jobid: jobid, polls: 0, lastPollAt: Date.now() });
    console.log('POOL submit ' + sceneId + ' on ' + (account || '(primary)') + ' → job ' + jobid + ' (' + pool.inflight.length + ' in flight)');
  } else {
    // Accepted with no jobid is not something to retry blindly — the scene is
    // set aside and the next pass will find it without a clip.
    done.push(sceneId);
    pool.done = done;
    console.log('POOL submit ' + sceneId + ': no jobid in the response, setting the scene aside');
  }
} else if (from === 'Pool Retry?') {
  // The job exists and is not finished yet. Only the counters move.
  const j = inflight.find(function (x) { return x.id === sceneId; });
  if (j) {
    j.polls = Number(j.polls || 0) + 1;
    j.lastPollAt = Date.now();
  }
} else {
  // Update Scene Record (the clip landed), Mark Video Prompt Rejected (given up
  // on), or Needs Clip? saying this scene already had one. Either way the scene
  // is off the pool's books and its account slot is free.
  drop(sceneId);
  unqueue(sceneId);
  if (done.indexOf(sceneId) < 0) done.push(sceneId);
  pool.done = done;
  console.log('POOL settled ' + sceneId + ' via ' + (from || '?') + ' (' + pool.inflight.length + ' in flight, ' + (pool.queue || []).length + ' queued)');
}

return [{ json: { pool: pool } }];

// Turn one webhook POST into the payload the `RG *` tail already eats.
//
// The site fires { scene_id } and this decides whether that scene can be
// re-shot at all, then hands `Prep Video Regen` exactly what
// `Evaluate Video Approval` hands it on the batch path — the same
// { id, motionPrompt, imageId, voiceUrl } — plus the project and scene rows
// the batch path gets from `IMG Load Project` and `Fetch Scene Videos`.
//
// WHY IT REFUSES RATHER THAN THROWS. `Prep Video Regen` throws on a scene with
// no Flow asset id or no motion prompt, and it carries no onError, so on the
// batch path that throw kills the whole execution. On this path a throw would
// be worse in a quieter way: the webhook run would die with `Regenerează
// Video` still true and nobody left to clear it, which is the stranded-flag
// dead end CLAUDE.md warns about once per in-flight flag. So every reason to
// stop is decided HERE, before the tail, and each one either clears the flag
// with an explanation or leaves a flag that was already gone alone.
// The POST, read from the webhook node by name rather than from $json:
// $json here is VRW Load Scene's row, and a body that arrived through a
// column alias would be a coupling nobody would expect to matter until the
// day someone renamed a column.
const hook = $('Video Regen Webhook').first().json;
const post = hook.body || hook;
const sceneId = String(post.scene_id || post.sceneId || '').trim();
const row = $input.all()[0] ? $input.all()[0].json : null;

const refuse = (reason, write) => [{ json: { ok: false, write: !!write, sceneId, reason } }];

if (!sceneId) throw new Error('VRW: no scene_id in the webhook body — nothing to regenerate.');
// A scene id that matches no row is the one case worth throwing on: there is
// no flag to clear and no row to write a reason onto, so failing loudly is
// the only way it is ever noticed.
if (!row || !row.scene) throw new Error('VRW: scene ' + sceneId + ' not found.');

const f = row.scene || {};
const projF = row.project || {};
const projectId = String(row.project_id || '');

// The flag is the request. If it is already false, either the producer
// cancelled it or a batch got there first — either way there is nothing to do
// and nothing to write. Ending quietly here is what makes the webhook safe to
// fire twice, which the site does whenever an approved image queues a clip
// and the producer also presses Regenerate.
if (f['Regenerează Video'] !== true) return refuse('the scene is not asking for a new clip (Regenerează Video is already false)', false);

// These two ARE the reasons `Prep Video Regen` throws. Catching them here
// turns "the film dies" into "the scene comes back with a sentence".
if (!f['Image Media ID']) return refuse('this scene has no Flow image id, so there is no still for Veo to animate — regenerate and approve its image first', true);
if (!String(f['Video Scenă URL'] || '').trim()) return refuse('this scene has no shot direction (Video Scenă URL), so there is nothing to shoot — write one in the Video step', true);

// `Observații Scenă` IS NOT A PRODUCER-ONLY FIELD, and that is what makes
// the reordering below dangerous without this line. Five nodes in this
// workflow write MACHINE text into it and none of them ever clears it:
// `VP Apply` ("AUTO-REWRITE-VIDEO (attempt N): the video filter refused
// this scene — …"), `Apply Rewritten Prompt`, `Mark Flow Upload Rejected`,
// `Mark Video Prompt Rejected` and `Mark Regen Filtered` (all "REJECTED by
// …"). `VP Apply` writes that note AND sets `Regenerează Video: true` in
// the same statement, so the very next poll arrives here with a machine
// sentence sitting in the producer's feedback slot.
//
// Before the reordering this was hidden by a bug: the note was appended
// after the legacy "Negative:" tail and `Submit Video Regen` cut it off.
// Strip-then-append fixes the producer's case and would have handed Veo
// "the new video MUST follow this: AUTO-REWRITE-VIDEO (attempt 2): the
// video filter refused this scene …" as a mandatory instruction. Worse, it
// would persist: nothing clears the field, so every later regeneration of
// that scene would carry it again.
//
// `Evaluate Image Approval` one gate upstream already solves this with the
// same test, and this is deliberately the same shape so the two stay
// greppable together. Extend BOTH if a sixth machine writer appears.
let feedback = String(f['Observații Scenă'] || '').trim();
if (/^(AUTO-|REJECTED)/i.test(feedback)) feedback = '';
// 2026-09-13 — WHERE THE PRODUCER'S CORRECTION LANDS IN THE PROMPT.
//
// `Video Scenă URL` holds the motion PROMPT, not a URL (historic field
// name, same everywhere in this workflow).
//
// This node used to build the regeneration brief in this order:
//
//     <stored prompt, legacy "Negative: …" tail and all>
//       + ' ADJUSTMENT REQUEST — the new video MUST follow this: …'
//
// which put the one piece of text a human actually typed AFTER the token
// "Negative:", i.e. inside a list of prohibitions. A producer typing "she
// should keep holding the stack" was handing the model one more thing to
// avoid.
//
// And it was worse than badly placed: it was DELETED. `Submit Video
// Regen` strips the legacy tail with split(/\s*Negative:\s*/i)[0] before
// composing today's guardrails, so on any scene whose stored prompt still
// carries that tail — 368 of the 504 rows written in the three weeks up to
// today — the split cut the prompt at "Negative:" and took everything
// BEFORE it, throwing the ADJUSTMENT REQUEST away with the tail. The
// producer rejected a clip, wrote what was wrong with it, waited a minute
// and a half, and got a re-roll of the identical brief. That is the shape
// of "regenerate does nothing".
//
// So: strip FIRST, then append the correction. The stored prompt is
// reduced to the ACTION ONLY with the same canonical split used by
// `Current Scene`, `End Frame Prompt` and (as an instruction) `VP Rewrite
// AI`, and the producer's words become part of that action. The
// guardrails — shot rules in front, world rules and the trailing noun
// list behind — are composed at submit time by `Submit Video Regen` and
// must not be here.
//
// Two downstream readers get this for free, and both already claimed it
// in their own comments:
//   - `RG End Frame Prompt` draws the after-frame from `motionPrompt` and
//     does NOT strip anything itself, so it was handing nano-banana-2
//     "no subtitles, no lip movement" as drawing instructions.
//   - `RG Motion Prep` judges the finished clip against `motionPrompt`.
//     The brief it scores is now the action plus the human's correction,
//     which is what its comment says it is.
//
// The 'ADJUSTMENT REQUEST — the new video MUST follow this: ' wording is
// quoted verbatim in both of those nodes' comments. If it ever changes,
// change it in all three.
//
// The tail-only edge must NEVER produce an empty prompt. `Prep Video
// Regen` throws "has no motion prompt" on one, and it carries no onError
// setting, so that throw aborts the WHOLE Media Generation execution —
// the batch loop, the image gate and the video gate for every other scene
// — and strands `Regenerează Video` true with no writer left inside the
// run to clear it. A row whose stored prompt is nothing but a tail is
// rare, but "rare" and "takes the film down with it" is not a trade worth
// making for tidiness. Falling back to the raw stored string restores
// exactly the pre-2026-09-13 behaviour for that one case and can only be
// better than nothing.
const storedPrompt = String(f['Video Scenă URL'] || '');
const action = storedPrompt.split(/\s*Negative:\s*/i)[0].trim();
let motionPrompt = action || storedPrompt.trim();
if (feedback) {
  // Defensive, and only against the literal section token: if a producer
  // types "Negative:" in their note, the submit-time split would truncate
  // the prompt at their own words. Softening the colon keeps every word
  // they wrote and leaves nothing downstream can read as a header.
  const note = feedback.replace(/\bNegative\s*:/gi, 'Negative,');
  motionPrompt += ' ADJUSTMENT REQUEST — the new video MUST follow this: ' + note + '.';
}

const regen = { id: sceneId, motionPrompt, imageId: f['Image Media ID'] || '', voiceUrl: f['Voiceover URL'] || '' };

console.log('VRW ' + sceneId + ': regenerating, ' + motionPrompt.length + ' chars of brief' + (feedback ? ', with the producer\'s correction' : ''));

return [{
  json: {
    ok: true,
    sceneId,
    projectId,
    regen,
    // What `Prep Video Regen` reads instead of IMG Load Project / Fetch Scene
    // Videos / Receive Batch Input when it sees this entry point.
    sceneFields: f,
    projectFields: projF,
    aspectRatio: String(projF['Format'] || '16:9') === '9:16' ? '9:16' : '16:9',
  },
}];

// ---------------------------------------------------------------------------
// REFERENCE ASSEMBLY — shared word for word by Build Image Request (batch),
// Evaluate Image Approval (the gate's regen) and IR Build Request (the site's
// regen). Change one, change all three: a re-rolled picture built from
// different references than its neighbours is the drift this exists to stop.
//
// Consistency comes from PICTURES the model is anchored to, never from prose:
//   - cast sheets   (castRefs / castSheets)   one per character, turnaround or portrait
//   - object sheets (objectRefs)              one per hero object (a car, a machine)
//   - set plates    (locationRefs)            one per bible location, wide, empty
//   - the producer's own photo                ground truth on scene 1
//   - the previous frame                      LAST, palette only
// Who and where come from the scene's own tags (`char:`, `obj:`, `loc:`),
// written by the segmenter; films made before the tags existed fall back to
// name matching on Prompt Vizual, exactly as the cast sheet did.
const CONS = (function () {
  const norm = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const tagsOf = (f) => (Array.isArray(f['Tag-uri Scenă']) ? f['Tag-uri Scenă'] : []).map((t) => String(t));
  const tagged = (f, prefix) => tagsOf(f).filter((t) => t.startsWith(prefix)).map((t) => t.slice(prefix.length).trim()).filter(Boolean);
  const mentions = (text, name, allGivens) => {
    const full = norm(name);
    const given = norm(name.split(/\s+/)[0] || '');
    const keys = (allGivens || []).filter((g) => g && g === given).length > 1 ? [full] : [full, given];
    return keys.some((k) => k.length > 2 && new RegExp('\\b' + esc(k) + '\\b').test(text));
  };
  // Which bible entries are IN this scene: tags first (exact names the
  // segmenter chose from the bible), name matching second.
  function present(f, entries, prefix, textFields) {
    const names = entries.map((e) => String((e || {}).name || '').trim()).filter(Boolean);
    const fromTags = tagged(f, prefix).map(norm);
    if (fromTags.length) return names.filter((n) => fromTags.includes(norm(n)));
    const text = ' ' + norm(textFields.map((k) => f[k] || '').join(' ')) + ' ';
    const givens = names.map((n) => norm(n.split(/\s+/)[0] || ''));
    return names.filter((n) => mentions(text, n, givens));
  }
  function plan(a) {
    // a: { f, opts, bible, prompt, prevId, userRefId, isFirstScene, afterRefusal, strict, strictNotes }
    const opts = a.opts || {}, bible = a.bible || {}, f = a.f || {};
    const castRefs = (opts.castRefs && typeof opts.castRefs === 'object') ? opts.castRefs : {};
    const castSheets = (opts.castSheets && typeof opts.castSheets === 'object') ? opts.castSheets : {};
    const objectRefs = (opts.objectRefs && typeof opts.objectRefs === 'object') ? opts.objectRefs : {};
    const locationRefs = (opts.locationRefs && typeof opts.locationRefs === 'object') ? opts.locationRefs : {};
    const chars = Array.isArray(bible.characters) ? bible.characters : [];
    const objs = Array.isArray(bible.objects) ? bible.objects : [];
    const locs = Array.isArray(bible.locations) ? bible.locations : [];
    const refs = []; // {id, role, name}
    const used = { cast: [], objects: [], location: '', user: false, palette: false };
    if (a.afterRefusal) {
      // A refusal is likeliest about a face; nothing is attached, the prompt
      // rewrite alone carries the retry. Same rule as before the sheets.
      return { refs, used, prompt: a.prompt };
    }
    const protagonist = (() => {
      const byRole = chars.find((c) => /protagonist|lead|main|hero/i.test(String((c || {}).role || '')));
      return String(((byRole || chars[0]) || {}).name || '');
    })();
    if (a.isFirstScene && a.userRefId) { refs.push({ id: a.userRefId, role: 'user', name: protagonist }); used.user = true; }
    // Cast: leads (turnaround sheets) first, then portraits; two at most —
    // a third sheet crowds the composition (measured on the cast sheet port).
    const inScene = present(f, chars, 'char:', ['Prompt Vizual']).filter((n) => castRefs[n]);
    inScene.sort((x, y) => ((castSheets[y] || {}).kind === 'turnaround') - ((castSheets[x] || {}).kind === 'turnaround'));
    for (const n of inScene) {
      if (used.user && norm(n) === norm(protagonist)) continue; // the photo is truer than the sheet
      if (used.cast.length >= 2) break;
      refs.push({ id: castRefs[n], role: 'cast', name: n }); used.cast.push(n);
    }
    const objsIn = present(f, objs, 'obj:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => objectRefs[n]);
    for (const n of objsIn) { if (used.objects.length >= 1) break; refs.push({ id: objectRefs[n], role: 'object', name: n }); used.objects.push(n); }
    const locIn = present(f, locs, 'loc:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => locationRefs[n]);
    if (locIn.length) { refs.push({ id: locationRefs[locIn[0]], role: 'place', name: locIn[0] }); used.location = locIn[0]; }
    // The previous frame, last, palette only — and only when there is room.
    if (a.prevId && refs.length < 5 && !refs.some((r) => r.id === a.prevId)) { refs.push({ id: a.prevId, role: 'palette', name: '' }); used.palette = true; }
    // The sentence names the references BY POSITION, so it is built from the
    // list rather than assumed.
    const parts = [];
    refs.forEach((r, i) => {
      const k = i + 1;
      if (r.role === 'user') parts.push('Reference image ' + k + ' is the producer\'s own photo and is GROUND TRUTH for that character: exactly the same face, hair, body and outfit.');
      else if (r.role === 'cast') parts.push('Reference image ' + k + ' is a character sheet of ' + r.name + ' shown from several angles: this character (a person, an animal or a creature, whatever the sheet shows) in the shot has EXACTLY that face or head, hair or markings, colours, build and wardrobe. Render ONE view of them inside the scene — never the sheet layout, never several copies, never the neutral backdrop.');
      else if (r.role === 'object') parts.push('Reference image ' + k + ' is a reference sheet of ' + r.name + ': the same object in the shot has exactly that design, colours, markings and materials — one instance, placed in the scene.');
      else if (r.role === 'place') parts.push('Reference image ' + k + ' is the PLACE (' + r.name + '): the same architecture, layout, landmarks, materials and the same arrangement of what stands where. Light, weather and time of day follow the text, not the plate; the plate is empty of people and its framing is not this shot\'s framing.');
      else if (r.role === 'palette') parts.push('The LAST reference image is only for colour palette and film look, never for layout and never for who or where anyone is.');
    });
    let prompt = a.prompt;
    if (parts.length) {
      prompt = parts.join(' ') + ' Compose the shot described here, which may place its subjects at any distance, angle or part of the location: ' + a.prompt;
      if (a.strict) prompt = 'STRICT MATCH — the previous attempt drifted from the references (' + String(a.strictNotes || 'identity or place did not match') + '). Wherever the text and the references disagree about how a person, object or place LOOKS, the references win. ' + prompt;
    }
    return { refs, used, prompt };
  }
  function apply(body, planned) {
    planned.refs.forEach((r, i) => { body['reference_' + (i + 1)] = r.id; });
    body.prompt = planned.prompt;
    return body;
  }
  return { norm, plan, apply, tagged };
})();
// ---------------------------------------------------------------------------
const expected = $('Sort & Cap Scenes').all().map(s => s.json.id);
const order = {};
expected.forEach((id, i) => order[id] = i);
const seen = new Set();
const recs = $input.all()
  .filter(r => order[r.json.id] !== undefined)
  .filter(r => { if (seen.has(r.json.id)) return false; seen.add(r.json.id); return true; })
  .slice()
  .sort((a, b) => order[a.json.id] - order[b.json.id]);
const regen = [];
// The gate's regen builds the SAME reference set the batch loop builds —
// sheets, object sheets, the set plate, the previous scene's picture last —
// through the shared assembler below, so a re-rolled picture is anchored
// exactly like its neighbours. After a REJECTED / AUTO-REWRITE note nothing
// is attached (the reference may hold what was refused).
const projF = ($('IMG Load Project').first().json.fields || {});
let regenOpts = {}; try { regenOpts = JSON.parse(projF['Editing Options'] || '{}') || {}; } catch (e) { regenOpts = {}; }
let regenBible = {}; try { regenBible = JSON.parse(projF['Story Bible'] || '{}') || {}; } catch (e) { regenBible = {}; }
try { if ($('Save Cast Refs').isExecuted) { const j = $('Save Cast Refs').first().json; if (j.cast_refs) regenOpts.castRefs = j.cast_refs; if (j.cast_sheets) regenOpts.castSheets = j.cast_sheets; if (j.object_refs) regenOpts.objectRefs = j.object_refs; } } catch (e) {}
try { if ($('Save Set Plates').isExecuted) { const j = $('Save Set Plates').first().json; if (j.location_refs) regenOpts.locationRefs = j.location_refs; } } catch (e) {}
const regenAspect = ($('Receive Batch Input').first().json.Aspect_Ratio === '9:16' ? '9:16' : '16:9');
recs.forEach((r, i) => {
  const f = r.json.fields || {};
  if (f['Regenerează Imagine'] === true) {
    const prevId = i > 0 ? String(((recs[i-1].json.fields || {})['Image Media ID']) || '') : '';
    let feedback = String(f['Observații Scenă'] || '').trim();
    const rejected = /^(AUTO-|REJECTED|Image regeneration REJECTED)/i.test(feedback);
    if (rejected) feedback = '';
    let prompt = f['Imagine First Frame'] || f['Prompt Vizual'] || '';
    if (feedback) prompt += '\n\nADJUSTMENT REQUEST — the new image MUST follow this: ' + feedback;
    const planned = CONS.plan({ f: f, opts: regenOpts, bible: regenBible, prompt: prompt, prevId: prevId, userRefId: '', isFirstScene: false, afterRefusal: rejected, strict: false, strictNotes: '' });
    const requestBody = CONS.apply({ email: 'fermafabiz@gmail.com', model: 'nano-banana-2', prompt: prompt, aspectRatio: regenAspect, count: 1, captchaRetry: 1 }, planned);
    regen.push({ id: r.json.id, prompt, prevId, requestBody, refs: planned.refs });
  }
});
const total = recs.length;
// This is the COMBINED asset gate. Takes and images are generated in one
// uninterrupted pass (audio loop first, image loop second) and reviewed
// together here, so the producer makes one visit instead of two before the
// expensive video stage. Voice regeneration is NOT dispatched from here —
// the standalone scene-voice-regen webhook covers it, exactly as it covered
// the old separate voice gate. Image regeneration keeps its in-batch chain
// (If Any Regen).
//
// A scene only counts as approved when its asset actually EXISTS — bulk
// approving before generation finished must not open the gate.
const imagesApproved = recs.filter(r => {
  const f = r.json.fields || {};
  const att = f['Imagine Scenă'];
  return f['Aprobare Imagine'] === true && Array.isArray(att) && att.length > 0;
}).length;
// Cinematic (silent) projects never synthesize: the pre-checked Aprobare
// Voce alone passes. AB Load Project runs whenever any scene lacked audio
// this pass; when it never ran (every scene already voiced) the catch
// leaves noSpeech false, which is correct for a project that has takes.
let noSpeech = false;
try { noSpeech = JSON.parse((($('AB Load Project').first().json.fields || {})['Editing Options']) || '{}').category === 'cinematic'; } catch (e) {}
const voicesApproved = recs.filter(r => {
  const f = r.json.fields || {};
  // A scene with NO narration at all (a silent hook shot — see Save scenes To
  // Airtable1's [SILENT] rule) never gets a take, so its approval cannot wait
  // for one; it is created approved, exactly like every scene of a silent film.
  const silentScene = String(f['Script Scenă'] || '').trim() === '';
  return f['Aprobare Voce'] === true && (noSpeech || silentScene || String(f['Voiceover URL'] || '') !== '');
}).length;
const allApproved = total > 0 && imagesApproved === total && voicesApproved === total;
return [{ json: { anyRegen: regen.length > 0, allApproved, regen, total, approved: imagesApproved, imagesApproved, voicesApproved } }];

const r = $json.regen;
if (!r) throw new Error('No regen payload.');
if (!r.imageId) throw new Error('Scene ' + r.id + ' has no Image Media ID — cannot regenerate its video (regenerate/approve its image first).');
if (!r.motionPrompt) throw new Error('Scene ' + r.id + ' has no motion prompt (Video Scenă URL).');

// Which model this re-roll deserves. Same rule as Current Scene, and the two
// must keep agreeing — a rescued clip that obeys a different rule from its
// neighbours is a new inconsistency.
//
// This is where the rescue actually fires: the main path only submits scenes
// with NO clip at all, so a scene on its third attempt can only arrive here.
// TWO ENTRY POINTS (2026-09-17), and this node is the only one that can
// tell them apart. Everything below it reads its context off THIS node's
// output, which is why the rest of the tail has no outside reference left
// and can be reached from a webhook at all.
const viaWebhook = (() => { try { return $('Video Regen Webhook').isExecuted; } catch (e) { return false; } })();

// The project row. On the batch path it is the one `IMG Load Project` fetched
// at the top of the run; on the webhook path `VRW Build Regen` carries the
// same row, read from hov.at_project in the same query as the scene. Both are
// the Airtable-shaped `fields` object, so everything after this is identical.
let projF = {};
try {
  projF = viaWebhook ? ($json.projectFields || {}) : ($('IMG Load Project').first().json.fields || {});
} catch (e) { projF = {}; }
let opts = {};
try { opts = JSON.parse(projF['Editing Options'] || '{}') || {}; } catch (e) { opts = {}; }

// 16:9 or 9:16, for `RG End Frame Prompt` and `Submit Video Regen`. The batch
// is told by the orchestrator's workflow input; a webhook run has no
// orchestrator, so it reads the project's own `Format` — which is the very
// field the orchestrator itself reads on Resume and Restart
// (`Fetch Project For Resume`: fields['Format'] || '16:9').
let aspectRatio = '16:9';
try {
  aspectRatio = viaWebhook
    ? String($json.aspectRatio || projF['Format'] || '16:9')
    : String($('Receive Batch Input').first().json.Aspect_Ratio || '16:9');
} catch (e) { aspectRatio = '16:9'; }
if (aspectRatio !== '9:16') aspectRatio = '16:9';
const FREE = 'veo-3.1-lite-low-priority';
const PAID = 'veo-3.1-quality';
const base = String(opts.videoModel || FREE);

// Takes already filed for this shot, read from the scene the gate fetched.
let takes = 0;
let sceneNote = '';
try {
  // Same row, fetched by whichever entry point ran: the gate's
  // `Fetch Scene Videos`, or `VRW Load Scene` one node upstream.
  const fields = viaWebhook
    ? ($json.sceneFields || {})
    : (($('Fetch Scene Videos').all().find((x) => x.json && x.json.id === r.id) || { json: {} }).json.fields || {});
  const v = fields['Versiuni Media'];
  const list = Array.isArray(v) ? v : JSON.parse(String(v || '[]'));
  takes = list.filter((e) => e && e.kind === 'video').length;
  sceneNote = String(fields['Observații Scenă'] || '').trim();
} catch (e) { takes = 0; }

// Two free takes the producer has already refused is the evidence that this
// shot is not something the free tier can do. Everything before that is a
// coin flip worth re-flipping for nothing.
const rescue = opts.rescueVideoModel === undefined ? PAID : String(opts.rescueVideoModel);
const model = (base === FREE && takes >= 2 && rescue && rescue !== FREE) ? rescue : base;
const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
// A SEED IS REPRODUCIBLE UNTIL IT IS REFUSED (2026-09-22). A refused clip
// files no take, so `takes` alone re-rolled the identical seed on every press
// of "Regenerate video" after a filter refusal — the one case where
// reproducing the last result is exactly what nobody wants. This path has no
// per-scene refusal counter (it is its own execution), but the machine note
// the ladder leaves behind says the last attempt was refused; when it does,
// the seed is deliberately fresh. Everywhere else it is what it always was.
const wasRefused = /^(AUTO-|REJECTED)/i.test(sceneNote);
const seed = hash(String(r.id || '') + ':' + takes + (wasRefused ? ':refused:' + Date.now() : '')) % 2147483647;
console.log('VIDEO REGEN ' + r.id + ': ' + model + (model === base ? '' : ' (rescue after ' + takes + ' takes)') + ', seed ' + seed + (wasRefused ? ' (fresh — the last attempt was refused)' : ''));

// `opts`, `aspectRatio` and `viaWebhook` ride along so that NOTHING after
// this node has to ask the outside world. `RG End Frame Prompt` and
// `RG Motion Prep` used to parse Editing Options out of `IMG Load Project`
// themselves and `Submit Video Regen` used to read the aspect off
// `Receive Batch Input`; all three now read them here.
return [{ json: Object.assign({}, r, { model: model, seed: seed, takes: takes, opts: opts, aspectRatio: aspectRatio, viaWebhook: viaWebhook }) }];

